applyInThisOrder:
    COMPLETED_PRIVATE_RUNTIME: ${{ needs.current-main-target.outputs.completed_private_runtime }}
    COMPLETED_RUNTIME_OUTCOME: ${{ needs.build-and-prepare.outputs.completed_runtime_outcome }}
    COMPLETED_PRIVATE_RUNTIME: ${{ inputs.completed_private_runtime }}
    COMPLETED_RUNTIME_OUTCOME: ${{ needs.build-and-prepare.outputs.completed_runtime_outcome }}
completed_private_runtime: ${{ needs.current-main-target.outputs.completed_private_runtime == 'true' }}
completed_private_runtime_pin: ${{ needs.current-main-target.outputs.completed_private_runtime_pin }}
completed_private_runtime: ${{ inputs.completed_private_runtime }}
completed_private_runtime_pin: ${{ needs.current-main-target.outputs.completed_private_runtime_pin }}
- name: Require one canonical target hour and completed-runtime decision
  id: target-selection
  shell: bash
  env:
    REQUESTED_COMPLETED: ${{ inputs.completed_private_runtime }}
    MANUAL_TARGET: ${{ steps.completed-target.outputs.target_hour }}
    MANUAL_PIN: ${{ steps.completed-target.outputs.completed_private_runtime_pin }}
    AUTO_OUTCOME: ${{ steps.automatic-completed-target.outcome }}
    AUTO_COMPLETED: ${{ steps.automatic-completed-target.outputs.completed_private_runtime }}
    AUTO_TARGET: ${{ steps.automatic-completed-target.outputs.target_hour }}
    AUTO_PIN: ${{ steps.automatic-completed-target.outputs.completed_private_runtime_pin }}
    CHECKPOINT_TARGET: ${{ steps.checkpoint-target.outputs.target_hour }}
    CACHE_TARGET: ${{ steps.cache-state.outputs.target_hour }}
  run: |
    set -euo pipefail
    case "$AUTO_OUTCOME:$AUTO_COMPLETED" in
      success:true)
        test "$REQUESTED_COMPLETED" = false
        test -z "$MANUAL_TARGET$MANUAL_PIN$CHECKPOINT_TARGET$CACHE_TARGET"
        completed=true
        target="$AUTO_TARGET"
        pin="$AUTO_PIN"
        ;;
      skipped:|success:false)
        test -z "$AUTO_TARGET$AUTO_PIN"
        completed="$REQUESTED_COMPLETED"
        if test "$completed" = true; then
          test "$AUTO_OUTCOME" = skipped
          test -z "$CHECKPOINT_TARGET$CACHE_TARGET"
          target="$MANUAL_TARGET"
          pin="$MANUAL_PIN"
        else
          test "$completed" = false
          test -z "$MANUAL_TARGET$MANUAL_PIN"
          target="${CHECKPOINT_TARGET:-$CACHE_TARGET}"
          pin=''
        fi
        ;;
      *) exit 1 ;;
    esac
    [[ "$target" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:00:00Z$ ]]
    if test "$completed" = true; then [[ "$pin" =~ ^[a-f0-9]{64}$ ]]; fi
    printf 'completed_private_runtime=%s\ntarget_hour=%s\ncompleted_private_runtime_pin=%s\n' \
      "$completed" "$target" "$pin" >> "$GITHUB_OUTPUT"
- name: Require one canonical target hour
  shell: bash
  env:
    TARGET_HOUR: ${{ steps.completed-target.outputs.target_hour || steps.checkpoint-target.outputs.target_hour || steps.cache-state.outputs.target_hour }}
  run: |
    set -euo pipefail
    [[ "$TARGET_HOUR" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:00:00Z$ ]]
- name: Select provider-free continuation for the default scheduled caller
  id: automatic-completed-target
  if: steps.automatic-completed-scope.outputs.eligible == 'true'
  env:
    GITHUB_TOKEN: ${{ github.token }}
    SUPABASE_URL: ${{ secrets.SUPABASE_URL }}
    SUPABASE_SERVICE_ROLE_KEY: ${{ secrets.SUPABASE_SERVICE_ROLE_KEY }}
    RAVRADAR_AUTOMATIC_COMPLETED_INPUTS: ${{ toJSON(inputs) }}
    RAVRADAR_AUTOMATIC_COMPLETED_REENTRY_ACTION: ${{ needs.operational-recovery-gate.outputs.recovery_action }}
  run: node scripts/select-automatic-completed-private-runtime.mjs

- name: Lock the canonical UTC production hour
  id: cache-state
  if: >-
    inputs.checkpoint_target_hour == '' && inputs.completed_private_runtime != true &&
    (steps.automatic-completed-target.outcome == 'skipped' ||
     steps.automatic-completed-target.outputs.completed_private_runtime == 'false')
- name: Lock the canonical UTC production hour
  id: cache-state
  if: inputs.checkpoint_target_hour == '' && inputs.completed_private_runtime != true
- name: Identify the default scheduled weather caller
  id: automatic-completed-scope
  if: >-
    github.actor == 'github-actions[bot]' && github.triggering_actor == 'github-actions[bot]' &&
    github.run_attempt == 1 && inputs.completed_private_runtime == false &&
    inputs.current_family_cold_start == false && inputs.quick_confirmation == false &&
    inputs.weather_state_epoch_bootstrap == false && inputs.weather_state_epoch_checkpoint_reentry == false &&
    inputs.native_sampling_identity_original_recovery == false &&
    inputs.completed_stage_source == '' && inputs.quick_progress_source == '' && inputs.checkpoint_target_hour == '' &&
    inputs.weather_state_epoch_archive_key == '' && inputs.weather_state_epoch_archive_catalog_sha256 == '' &&
    inputs.weather_state_epoch_raw_cache_key == ''
  run: echo 'eligible=true' >> "$GITHUB_OUTPUT"

- uses: actions/setup-node@v7
  if: inputs.completed_private_runtime == true || steps.automatic-completed-scope.outputs.eligible == 'true'
  with:
    node-version: 22
- uses: actions/setup-node@v7
  if: inputs.completed_private_runtime == true
  with:
    node-version: 22
target_hour: ${{ steps.target-selection.outputs.target_hour }}
completed_private_runtime: ${{ steps.target-selection.outputs.completed_private_runtime }}
completed_private_runtime_pin: ${{ steps.target-selection.outputs.completed_private_runtime_pin }}
target_hour: ${{ steps.completed-target.outputs.target_hour || steps.checkpoint-target.outputs.target_hour || steps.cache-state.outputs.target_hour }}
completed_private_runtime_pin: ${{ steps.completed-target.outputs.completed_private_runtime_pin }}
